import { boardCases } from '../src/data/boardCases';
import { expect, test } from '../src/fixtures/test';

// FR-2: one test per row of tests/data/board-cases.json, all generated by this one loop
// (C-3, NFR-01, NFR-02). Adding a case means adding a JSON row; nothing here names a case.
// `boardPage` depends on the `loggedIn` fixture, so every test first logs in through the UI in
// its own fresh page (NFR-08), shown as the "Login to Demo App" step.
test.describe('Board', () => {
  for (const c of boardCases) {
    test(`${c.id}: "${c.task}" is in "${c.column}" on ${c.project} with tags ${c.tags.join(', ')}`, async ({
      boardPage,
    }) => {
      await test.step('Navigate to project', async () => {
        await boardPage.openProject(c.project);
        await expect(
          boardPage.openedProject(c.project),
          `Project "${c.project}" is open`,
        ).toBeVisible();
      });

      const card = boardPage.card(c.column, c.task);

      await test.step('Verify column', async () => {
        await expect(
          boardPage.column(c.column),
          `Column "${c.column}" is on the board`,
        ).toBeVisible();
        await expect(
          card,
          `Card "${c.task}" is in column "${c.column}"`,
        ).toBeVisible();
      });

      await test.step('Verify tags', async () => {
        // The count comes first, so a missing or extra tag fails here with both numbers;
        // a wrong tag name then fails below on that name (NFR-06).
        await expect(
          boardPage.tags(card),
          `Card "${c.task}" has exactly ${c.tags.length} tag(s): ${c.tags.join(', ')}`,
        ).toHaveCount(c.tags.length);
        for (const tag of c.tags) {
          await expect(
            boardPage.tag(card, tag),
            `Card "${c.task}" has tag "${tag}"`,
          ).toBeVisible();
        }
      });
    });
  }
});
